@namespace sv_763dd8ea9d1b47349ebea5a99125a7a9.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClicked(stepIndex)" role="button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
            @if (stepIndex < StepNames.Length - 1)
            {
                <li class="step-connector @status" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@namespace sv_763dd8ea9d1b47349ebea5a99125a7a9.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" value="@Company" @onchange="e => { Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" value="@Title" @onchange="e => { Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd"))" disabled="@IsCurrent" @onchange="OnEndDateChanged" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="OnIsCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => { Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, IsCurrent ? null : EndDate, IsCurrent, Description));
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var d)) StartDate = d;
        NotifyChanged();
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        NotifyChanged();
    }

    private void OnIsCurrentChanged(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

