toolArgs.file_text:
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    border-radius: 0.5rem;
    font-size: 0.875rem;
    transition: all 0.2s;
}

.step-item.active {
    background: #e8f0fe;
    color: #1a73e8;
    font-weight: 600;
}

.step-item.completed {
    cursor: pointer;
    color: #188038;
}

.step-item.completed:hover {
    background: #e6f4ea;
}

.step-item.dimmed {
    color: #9aa0a6;
}

.step-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border-radius: 50%;
    font-size: 0.75rem;
    font-weight: 600;
}

.step-item.active .step-badge {
    background: #1a73e8;
    color: white;
}

.step-item.completed .step-badge {
    background: #188038;
    color: white;
}

.step-item.dimmed .step-badge {
    background: #e8eaed;
    color: #9aa0a6;
}

.step-connector {
    width: 1.5rem;
    height: 2px;
    background: #e8eaed;
}

.step-connector.completed {
    background: #188038;
}

.step-connector.active {
    background: #1a73e8;
}

.checkmark {
    font-size: 0.875rem;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e8eaed;
    border-radius: 0.75rem;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #3c4043;
    font-size: 0.875rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.625rem 0.75rem;
    border: 1px solid #dadce0;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #1a73e8;
    box-shadow: 0 0 0 2px rgba(26, 115, 232, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: 400 !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e8eaed;
}

.btn-primary {
    background: #1a73e8;
    color: white;
    border: none;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #1557b0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #1a73e8;
    border: 1px solid #1a73e8;
    padding: 0.625rem 1.5rem;
    border-radius: 0.375rem;
    font-size: 0.9375rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-outline:hover {
    background: #e8f0fe;
}

.btn-secondary {
    background: #f1f3f4;
    color: #3c4043;
    border: 1px solid #dadce0;
    padding: 0.5rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.875rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-secondary:hover {
    background: #e8eaed;
}

.btn-remove {
    background: none;
    color: #d93025;
    border: 1px solid #d93025;
    padding: 0.375rem 0.75rem;
    border-radius: 0.375rem;
    font-size: 0.8125rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-remove:hover {
    background: #fce8e6;
}

.btn-link {
    background: none;
    border: none;
    color: #1a73e8;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #1557b0;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Entry Cards */
.entry-card {
    border: 1px solid #e8eaed;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-card h4 {
    margin: 0 0 1rem 0;
    color: #5f6368;
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* Error Messages */
.error-message {
    background: #fce8e6;
    color: #d93025;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.875rem;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.8125rem;
    color: #5f6368;
    margin-top: 0.375rem;
}

.char-count.over-limit {
    color: #d93025;
    font-weight: 500;
}

/* Hint */
.hint {
    color: #5f6368;
    font-size: 0.875rem;
    margin-bottom: 1.5rem;
}

/* Review Section */
.review-section {
    border-bottom: 1px solid #e8eaed;
    padding-bottom: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.375rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #5f6368;
    font-size: 0.875rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.875rem;
}

.review-entry {
    padding: 0.5rem 0;
    font-size: 0.875rem;
}

.review-entry + .review-entry {
    border-top: 1px solid #f1f3f4;
    margin-top: 0.5rem;
    padding-top: 0.75rem;
}

.date-range {
    color: #5f6368;
    font-size: 0.8125rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.875rem;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 0.375rem;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 4rem;
    height: 4rem;
    background: #188038;
    color: white;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    margin-bottom: 1.5rem;
}

.confirmation h3 {
    color: #188038;
    margin-bottom: 1rem;
}

.confirmation p {
    color: #5f6368;
    font-size: 1rem;
}

